#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<int> pancakeSort(std::vector<int>& arr) {
        std::vector<int> ans;
        int n = arr.size();
        std::vector<int> a = arr;
        for (int target = n; target > 1; --target) {
            int idx = std::find(a.begin(), a.end(), target) - a.begin();
            if (idx == target - 1) continue;
            if (idx != 0) {
                ans.push_back(idx + 1);
                std::reverse(a.begin(), a.begin() + idx + 1);
            }
            ans.push_back(target);
            std::reverse(a.begin(), a.begin() + target);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public List<Integer> pancakeSort(int[] arr) {
        List<Integer> ans = new ArrayList<>();
        int n = arr.length;
        int[] a = arr.clone();
        for (int target = n; target > 1; target--) {
            int idx = 0;
            while (a[idx] != target) idx++;
            if (idx == target - 1) continue;
            if (idx != 0) {
                ans.add(idx + 1);
                reverse(a, 0, idx);
            }
            ans.add(target);
            reverse(a, 0, target - 1);
        }
        return ans;
    }

    private void reverse(int[] a, int l, int r) {
        while (l < r) {
            int t = a[l];
            a[l] = a[r];
            a[r] = t;
            l++;
            r--;
        }
    }
}

function pancakeSort(arr) {
    const ans = [];
    const n = arr.length;
    const a = [...arr];
    for (let target = n; target > 1; target--) {
        const idx = a.indexOf(target);
        if (idx === target - 1) continue;
        if (idx !== 0) {
            ans.push(idx + 1);
            let l = 0, r = idx;
            while (l < r) {
                [a[l], a[r]] = [a[r], a[l]];
                l++; r--;
            }
        }
        ans.push(target);
        let l = 0, r = target - 1;
        while (l < r) {
            [a[l], a[r]] = [a[r], a[l]];
            l++; r--;
        }
    }
    return ans;
}
